package com.dormrepair.transfer;
import com.dormrepair.common.enums.*;import com.dormrepair.common.exception.BusinessException;import com.dormrepair.domain.entity.*;import com.dormrepair.domain.mapper.*;import com.dormrepair.order.service.CurrentWorkerResolver;import com.dormrepair.security.model.LoginUser;import com.dormrepair.transfer.dto.*;import com.dormrepair.transfer.enums.*;import com.dormrepair.transfer.service.WorkerTransferRequestService;import com.dormrepair.transfer.service.WorkerTransferRequestTransactionService;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class WorkerTransferRequestServiceTest {RepairOrderMapper orders;RepairTransferRequestMapper transfers;SysIdempotentRecordMapper idem;WorkerTransferRequestService service;
 @BeforeEach void setup(){orders=mock(RepairOrderMapper.class);transfers=mock(RepairTransferRequestMapper.class);idem=mock(SysIdempotentRecordMapper.class);CurrentWorkerResolver resolver=mock(CurrentWorkerResolver.class);when(resolver.resolveCurrentWorkerId()).thenReturn(10L);WorkerTransferRequestTransactionService tx=new WorkerTransferRequestTransactionService(idem,transfers,mock(SysOperationLogMapper.class));service=new WorkerTransferRequestService(orders,transfers,idem,resolver,tx,new ObjectMapper());LoginUser u=new LoginUser(20L,"worker","维修员",UserRoleEnum.WORKER);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void createKeepsOrderUnchanged(){RepairOrder o=order(2,10L);when(orders.selectById(1L)).thenReturn(o);doAnswer(i->{((RepairTransferRequest)i.getArgument(0)).setId(8L);return 1;}).when(transfers).insert(any());var out=service.create(1L,new CreateTransferRequest("b1",TransferReasonType.NO_SKILL,"不会修"));assertThat(out.requestId()).isEqualTo(8L);verify(orders,never()).casMarkPending(any(),any(),any());verify(transfers).insert(argThat(r->r.getOriginalAssigneeId()==10L&&r.getApprovalStatus()==0));}
 @Test void rejectsOtherWorkersOrder(){when(orders.selectById(1L)).thenReturn(order(2,99L));assertThatThrownBy(()->service.create(1L,new CreateTransferRequest("b1",TransferReasonType.NO_SKILL,null))).isInstanceOf(BusinessException.class).extracting("code").isEqualTo(17002);}
 @Test void rejectsSecondPendingRequest(){when(orders.selectById(1L)).thenReturn(order(2,10L));when(transfers.selectPendingByOrderId(1L)).thenReturn(new RepairTransferRequest());assertThatThrownBy(()->service.create(1L,new CreateTransferRequest("b2",TransferReasonType.OVERLOAD,null))).isInstanceOf(BusinessException.class).extracting("code").isEqualTo(19002);}
 private RepairOrder order(int status,Long worker){RepairOrder o=new RepairOrder();o.setId(1L);o.setStatus(status);o.setCurrentAssigneeId(worker);o.setDeleted(0);return o;}}
